const body = $json.body || {};
const defauts = ['parentalitebienveillante', 'emotionsenfant', 'gentleparenting'];
let hashtags = Array.isArray(body.hashtags) ? body.hashtags.filter(h => /^[\w]+$/.test(String(h))) : [];
if (!hashtags.length) hashtags = defauts;
return [{ json: { hashtags: hashtags.slice(0, 5) } }];

// Une panne Apify sur une plateforme ne doit pas annuler l'autre :
// les items en erreur (onError continueRegularOutput) sont ecartes ici.
const tiktok = $('Apify TikTok').all().map(i => i.json).filter(x => x && !x.error);
const insta = $input.all().map(i => i.json).filter(x => x && !x.error);

const EXCLUS = new Set(['anna.ollivier.psy', 'annaollivierpsy']);
const candidats = new Map();

function ajouter(plateforme, handle, nom, url, engagement, followers) {
  if (!handle || EXCLUS.has(handle.toLowerCase())) return;
  const k = plateforme + ':' + handle.toLowerCase();
  const c = candidats.get(k) || { plateforme, handle, nom: nom || handle, url, engagements: [], followers: null };
  c.engagements.push(engagement || 0);
  if (followers) c.followers = followers;
  candidats.set(k, c);
}

for (const it of tiktok) {
  const a = it.authorMeta || {};
  if (!a.name) continue;
  ajouter('TikTok', a.name, a.nickName, 'https://www.tiktok.com/@' + a.name, it.playCount || 0, a.fans || null);
}
for (const it of insta) {
  if (!it.ownerUsername) continue;
  const eng = (it.videoPlayCount != null) ? it.videoPlayCount : (it.likesCount || 0);
  ajouter('Instagram', it.ownerUsername, it.ownerFullName || it.ownerUsername,
    'https://www.instagram.com/' + it.ownerUsername + '/', eng, null);
}

// Seuils : TikTok pic >= 10000 vues ; Instagram (flux recent bruite) pic >= 200.
const retenus = [...candidats.values()].map(c => ({
  ...c,
  maxEng: Math.max(...c.engagements),
})).filter(c => c.plateforme === 'TikTok' ? c.maxEng >= 10000 : c.maxEng >= 200)
  .sort((a, b) => b.maxEng - a.maxEng).slice(0, 15);

return [{ json: { candidats: retenus } }];

// Idempotence : ecarter les handles deja presents dans Comptes Concurrents.
const existants = new Set(
  $('Lire Comptes Existants').all()
    .map(i => {
      const h = ((i.json.properties || {})['Handle'] || {}).rich_text || [];
      return h.length ? h[0].plain_text.toLowerCase() : null;
    })
    .filter(Boolean)
);
const date = new Date().toISOString().split('T')[0];
const sortie = [];
for (const c of ($('Agreger Candidats').first().json.candidats || [])) {
  if (existants.has(String(c.handle).toLowerCase())) continue;
  sortie.push({ json: {
    nom: String(c.nom).slice(0, 100),
    handle: c.handle,
    plateforme: c.plateforme,
    url: c.url,
    followers: c.followers || null,
    note: 'Candidat Module E ' + date + ' — pic ' + c.maxEng.toLocaleString('fr-FR') + ' vues/likes, hashtags parentalité. À valider (cocher Actif).',
  }});
}
return sortie;
